# 2. Build Gold Dataset: >= 150 claims with entity types, relations, offsets, and dev/test split
# Entity types: Substation, TransmissionLine, PowerEquipment, VoltageClass, FaultType, ProtectionRelay, WeatherPhenomenon
# Relation types: LOCATED_AT, OPERATES_AT_VOLTAGE, AFFECTED_BY_FAULT, TRIGGERED_PROTECTION, CAUSED_BY_WEATHER, CONNECTED_TO

CLAIMS = []
claim_id_counter = 1

def add_claim(doc_id, text_snippet, s, s_type, p, o, o_type, confidence=1.0):
    global claim_id_counter
    CLAIMS.append({
        "claim_id": f"CLM-{claim_id_counter:03d}",
        "doc_id": doc_id,
        "evidence_quote": text_snippet,
        "subject": s,
        "subject_type": s_type,
        "predicate": p,
        "object": o,
        "object_type": o_type,
        "confidence": confidence,
        "annotator_1": True,
        "annotator_2": True if random.random() > 0.05 else False
    })
    claim_id_counter += 1

